return items.map(item => {
  const binary = item.binary || {};
  const attachmentKey = Object.keys(binary)[0] || 'attachment_0';
  const attachment = binary[attachmentKey] || {};

  return {
    json: {
      emailSubject: item.json.subject || '',
      senderEmail: item.json.from?.value?.[0]?.address || '',
      senderName: item.json.from?.value?.[0]?.name || '',
      receivedDate: new Date().toISOString().replace('T', ' ').substring(0, 19),
      emailBody: item.json.text || '',
      attachmentName: attachment.fileName || '',
      attachmentData: JSON.stringify(attachment) || '',
      attachmentMimeType: attachment.mimeType || '',
      documentId: `RE-${new Date().toISOString().replace(/[-:T.]/g, '').slice(0, 15)}`
    },
    binary // ✅ preserve the original attachment binary for upload later
  };
});

const item = $input.item;

const subject = item.json.emailSubject?.toLowerCase() || '';
const body = item.json.emailBody?.toLowerCase() || '';
const filename = item.json.attachmentName?.toLowerCase() || '';

let documentType = 'Unknown';
let storageFolder = 'Property Documents';

// Identify document type
if (
  subject.includes('offer') ||
  subject.includes('purchase offer') ||
  body.includes('offer to purchase') ||
  filename.includes('offer')
) {
  documentType = 'Purchase Offer';
  storageFolder = 'Purchase Offers';
} else if (
  subject.includes('lease application') ||
  subject.includes('rental application') ||
  body.includes('application') ||
  filename.includes('application')
) {
  documentType = 'Lease Application';
  storageFolder = 'Lease Applications';
} else if (
  subject.includes('contract') ||
  filename.includes('contract')
) {
  documentType = 'Contract';
  storageFolder = 'Contracts';
} else {
  documentType = 'Property Document';
  storageFolder = 'Property Documents';
}

return {
  json: {
    documentType,
    storageFolder
  },
  binary: item.binary // ✅ Keep Gmail attachment for upload
};

const offerAmount = parseFloat($('Parse Extracted Data').first().json.offerAmount)  || 0;
const askingPrice = parseFloat($('Find Property in Database').first().json['Asking Price']) || 0;

// Calculate difference
const differenceAmount = offerAmount - askingPrice;
const differencePercent = askingPrice > 0 ? ((differenceAmount / askingPrice) * 100).toFixed(2) : 0;

// Determine offer strength
let offerStrength = 'Below Market';
if (differencePercent >= 0) {
  offerStrength = 'At or Above Asking';
} else if (differencePercent >= -5) {
  offerStrength = 'Competitive';
} else if (differencePercent >= -10) {
  offerStrength = 'Below Asking';
} else {
  offerStrength = 'Significantly Below';
}

// Calculate priority score (0-100)
let priorityScore = 50; // Base score

// Offer amount scoring
if (differencePercent >= 5) priorityScore += 25;
else if (differencePercent >= 0) priorityScore += 20;
else if (differencePercent >= -5) priorityScore += 10;
else if (differencePercent >= -10) priorityScore += 5;
else priorityScore -= 10;

// Financing scoring
const financingType = ($('Parse Extracted Data').first().json.financingType || '').toLowerCase();
if (financingType.includes('cash')) priorityScore += 20;
else if ($('Parse Extracted Data').first().json.preApproved === 'Yes') priorityScore += 15;
else priorityScore += 5;

// Contingencies scoring
const contingencies = $('Parse Extracted Data').first().json.contingencies || [];
if (contingencies.length === 0) priorityScore += 10;
else if (contingencies.length <= 2) priorityScore += 5;
else priorityScore -= 5;

// Inspection period scoring
const inspectionPeriod = parseInt($('Parse Extracted Data').first().json.inspectionPeriod) || 10;
if (inspectionPeriod <= 5) priorityScore += 5;
else if (inspectionPeriod <= 10) priorityScore += 2;

// Red flags
const redFlags = $('Parse Extracted Data').first().json.redFlags || '';
if (redFlags.length > 0) priorityScore -= 15;

// Cap score between 0-100
priorityScore = Math.max(0, Math.min(100, priorityScore));

// Determine priority level
let priorityLevel = 'Low';
if (priorityScore >= 80) priorityLevel = 'Critical - Act Now';
else if (priorityScore >= 65) priorityLevel = 'High Priority';
else if (priorityScore >= 50) priorityLevel = 'Medium Priority';

return {
  json: {
    offerAmount: offerAmount,
    askingPrice: askingPrice,
    differenceAmount: differenceAmount,
    differencePercent: differencePercent,
    offerStrength: offerStrength,
    priorityScore: priorityScore,
    priorityLevel: priorityLevel
  }
};

const monthlyIncome = parseFloat($('Parse Extracted Data').first().json.monthlyIncome) || 0;
const monthlyRent = parseFloat($('Find Property in Database').first().json['Monthly Rent']) || 0;

// Calculate income to rent ratio
const incomeToRentRatio = monthlyRent > 0 ? (monthlyIncome / monthlyRent).toFixed(2) : 0;

// Check if meets 3x rent rule
const meetsIncomeRequirement = incomeToRentRatio >= 3;

// Extract credit score
const creditScore = parseInt($('Parse Extracted Data').first().json.creditScore) || 0;

// Determine credit rating
let creditRating = 'Unknown';
if (creditScore >= 740) creditRating = 'Excellent';
else if (creditScore >= 700) creditRating = 'Very Good';
else if (creditScore >= 650) creditRating = 'Good';
else if (creditScore >= 600) creditRating = 'Fair';
else if (creditScore > 0) creditRating = 'Poor';

// Calculate priority score (0-100)
let applicationScore = 50; // Base score

// Income scoring (most important)
if (incomeToRentRatio >= 4) applicationScore += 25;
else if (incomeToRentRatio >= 3.5) applicationScore += 20;
else if (incomeToRentRatio >= 3) applicationScore += 15;
else if (incomeToRentRatio >= 2.5) applicationScore += 5;
else applicationScore -= 20;

// Credit score scoring
if (creditScore >= 740) applicationScore += 20;
else if (creditScore >= 700) applicationScore += 15;
else if (creditScore >= 650) applicationScore += 10;
else if (creditScore >= 600) applicationScore += 5;
else if (creditScore > 0) applicationScore -= 10;

// Employment status
const employment = ($('Parse Extracted Data').first().json.employmentStatus || '').toLowerCase();
if (employment.includes('employed')) applicationScore += 10;
else if (employment.includes('self-employed')) applicationScore += 5;
else if (employment.includes('retired')) applicationScore += 5;

// Red flags - major deductions
const redFlags = $('Parse Extracted Data').first().json.redFlags || '';
if (redFlags.toLowerCase().includes('eviction')) applicationScore -= 30;
if (redFlags.toLowerCase().includes('bankruptcy')) applicationScore -= 20;
if (redFlags.toLowerCase().includes('criminal')) applicationScore -= 15;

// Cap score
applicationScore = Math.max(0, Math.min(100, applicationScore));

// Determine application status
let applicationStatus = 'Rejected';
if (applicationScore >= 75) applicationStatus = 'Highly Qualified';
else if (applicationScore >= 60) applicationStatus = 'Qualified';
else if (applicationScore >= 45) applicationStatus = 'Conditional Approval';
else if (applicationScore >= 30) applicationStatus = 'Needs Review';

// Priority level
let priorityLevel = 'Low';
if (applicationScore >= 75) priorityLevel = 'High Priority';
else if (applicationScore >= 60) priorityLevel = 'Medium Priority';

return {
  json: {
    monthlyIncome: monthlyIncome,
    monthlyRent: monthlyRent,
    incomeToRentRatio: incomeToRentRatio,
    meetsIncomeRequirement: meetsIncomeRequirement,
    creditScore: creditScore,
    creditRating: creditRating,
    applicationScore: applicationScore,
    applicationStatus: applicationStatus,
    priorityLevel: priorityLevel
  }
};

// Check which type of document this is
const documentType = $('Parse Extracted Data').item.json.documentType;

let priorityScore = 0;
let isHighPriority = false;
let priorityLevel = 'Standard';

// Get the appropriate score based on document type
if (documentType.includes('Purchase') || documentType.includes('Offer')) {
  // This is a purchase offer - get offer analysis score
  priorityScore = $('Calculate Offer Metrics').item.json.priorityScore || 0;
  isHighPriority = priorityScore >= 80;
  priorityLevel = priorityScore >= 80 ? 'High Priority' : 'Standard';
} else if (documentType.includes('Lease') || documentType.includes('Application')) {
  // This is a lease application - get application analysis score
  priorityScore = $('Calculate Application Analysis').item.json.applicationScore || 0;
  isHighPriority = priorityScore >= 75;
  priorityLevel = priorityScore >= 75 ? 'High Priority' : 'Standard';
} else {
  // Unknown document type - treat as standard priority
  isHighPriority = false;
  priorityLevel = 'Standard';
}

return {
  json: {
    priorityScore: priorityScore,
    isHighPriority: isHighPriority,
    priorityLevel: priorityLevel,
    documentType: documentType
  }
};
